class NextDecodeHover{static instances=[];constructor(element){this.element=element;this.inner=element.querySelector(".dan-decode-hover__inner");this.delay=element.getAttribute("data-delay");this.duration=element.getAttribute("data-duration");this.ease=element.getAttribute("data-ease");this.decodeAlphabet=element.getAttribute("data-decodealphabet");this.fromRight=element.getAttribute("data-from-right")=="1";this.originalText=this.inner.innerHTML.split("");this.scrambledText=[];this.originalText.forEach((_,index)=>(this.scrambledText[index]=this.getRandomChar()));this.boundMouseEnterHandler=this.handleMouseEnter.bind(this);this.element.addEventListener('mouseenter',this.boundMouseEnterHandler)}
getRandomChar(){let char=this.decodeAlphabet[Math.floor(Math.random()*this.decodeAlphabet.length)];return Math.random()>0.5?char:char.toUpperCase()}
handleMouseEnter(){let timeline=gsap.timeline();let lastProgress=0;timeline.fromTo(this.inner,{innerHTML:this.scrambledText.join("")},{duration:this.originalText.length/parseFloat(this.duration),ease:this.ease,delay:parseFloat(this.delay),onUpdate:()=>{let currentProgress=Math.floor(timeline.progress()*this.originalText.length);if(lastProgress!==currentProgress){lastProgress=currentProgress;this.originalText.forEach((_,index)=>(this.scrambledText[index]=this.getRandomChar()));let visibleOriginal=this.originalText.join("").substring(currentProgress,0);let visibleScrambled=this.scrambledText.join("").substring(this.scrambledText.length-currentProgress,0);if(this.fromRight){visibleOriginal=this.scrambledText.join("").substring(this.scrambledText.length-currentProgress,0);visibleScrambled=this.originalText.join("").substring(this.originalText.length-currentProgress)}
this.inner.innerHTML=visibleOriginal+visibleScrambled}}})}
destroy(){this.element.removeEventListener('mouseenter',this.boundMouseEnterHandler)}
static destroyAllInstances(){NextDecodeHover.instances.forEach(instance=>instance.destroy());NextDecodeHover.instances=[]}}
function dancepad_decode_hover(){NextDecodeHover.destroyAllInstances();document.querySelectorAll(".dan-decode-hover").forEach((element)=>{const decoder=new NextDecodeHover(element);NextDecodeHover.instances.push(decoder)})}